window.__tourismCourseQuestions = {"history/lecture-01":{"source":"تاريخ مصر القديم، المحاضرة 1 (ملف المحاضرة المعتمد)، صفحات 1–7 من الملزمة؛ PDF 7 صفحة","trueFalse":[{"statement":"ارتبط انتقال الإنسان من الهضاب إلى وادي النيل بتغير المناخ وجفاف المراعي.","answer":true,"explanation":"مع تراجع الأمطار جفت المراعي على الهضاب، فتوجهت الحيوانات إلى الماء في الوادي وتبعها الإنسان بحثًا عن الغذاء والاستقرار."},{"statement":"بدأ إنتاج الغذاء قبل استقرار الإنسان في الوادي وممارسة الزراعة.","answer":false,"explanation":"كان جمع الموارد والصيد أسبق؛ وأسهم الاستقرار قرب النيل في ظهور الزراعة وتربية الحيوان، أي إنتاج الغذاء بدل الاكتفاء بجمعه."},{"statement":"تفسر الجغرافيا التاريخية نشأة الحضارة بتفاعل الإنسان والبيئة معًا.","answer":true,"explanation":"وفّر النيل الماء والتربة، لكن تنظيم الري والزراعة والاستقرار نتج عن عمل الإنسان؛ لذلك لا تكفي البيئة وحدها لتفسير الحضارة."},{"statement":"يرى أنصار الحتمية الجغرافية أن دور الإنسان وحده يفسر قيام الحضارة المصرية.","answer":false,"explanation":"الحتمية الجغرافية تعطي البيئة الدور الحاسم؛ أما المنهج التفاعلي فيجمع أثر الطبيعة وجهد الإنسان."},{"statement":"ساعد استئناس الحيوان وزراعة النبات على تحول المجتمع من جمع الغذاء إلى إنتاجه.","answer":true,"explanation":"أصبح الغذاء يُنتج بالزراعة وتربية الحيوان، ومعه ترسخت القرى والحاجة إلى تنظيم العمل والمياه."},{"statement":"كان استمرار الحضارة المصرية يعني غياب كل فترات الضعف والانقطاع السياسي.","answer":false,"explanation":"يشير الاستمرار الحضاري إلى قدرة المجتمع على التجدد عبر زمن طويل؛ فقد وقعت فترات ضعف وانتقال دون زوال تاريخ مصر المتصل."}],"essay":[{"question":"اشرح أثر نهر النيل والتغير المناخي في نشأة التجمعات البشرية بوادي النيل.","answer":"تراجعت الأمطار وجفت مناطق من الهضاب، فاتجهت الحيوانات ثم الإنسان إلى ضفاف النيل. وفر الوادي الماء والتربة وبيئة الاستقرار، فتهيأت جماعاته للزراعة ونشأة الحضارة."},{"question":"قارن بين مرحلتي جمع الغذاء وإنتاجه في وادي النيل.","answer":"في مرحلة الجمع اعتمد الإنسان على موارد البيئة الموجودة. ومع الاستقرار في الوادي بدأ إنتاج الغذاء بالزراعة وتربية الموارد، وهو تحول ارتبط بالعصر الحجري الحديث."},{"question":"كيف يفسر منهج الجغرافيا التاريخية نشأة الحضارة في وادي النيل؟","answer":"يبحث في التأثير المتبادل بين المكان والإنسان: أتاح النيل الماء والتربة ومسار الاتصال، واستثمر الإنسان هذه الموارد بالزراعة وتنظيم الري وبناء القرى. لا يفسر قيام الحضارة عامل واحد بمعزل عن الآخر."},{"question":"ما الصلة بين التغير المناخي والثورة الزراعية في وادي النيل؟","answer":"تراجع المطر على الهضاب فانتقل الحيوان والإنسان إلى الوادي. ساعد الاستقرار قرب الماء والتربة الخصبة على استنبات البذور وتربية الحيوان؛ وهكذا تحول الاقتصاد تدريجيًا من الصيد وجمع الغذاء إلى إنتاجه."}]},"history/lecture-02":{"source":"تاريخ مصر القديم، المحاضرة 2 (ملف المحاضرة المعتمد)، صفحات 8–21 من الملزمة؛ PDF 14 صفحة","trueFalse":[{"statement":"تعد قوائم أبيدوس والكرنك وسقارة وبردية تورين من مصادر تاريخ مصر القديمة.","answer":true,"explanation":"تسجل هذه القوائم أسماء ملوك أو تسلسلًا للحكم، وتساعد مقارنتها بالنقوش والآثار في إعادة بناء التسلسل التاريخي."},{"statement":"تكفي روايات المؤرخين الكلاسيكيين وحدها لإعادة بناء تاريخ مصر القديمة.","answer":false,"explanation":"قد يكتب المؤرخ الكلاسيكي بعد الحدث بقرون أو ينقل روايات غير دقيقة؛ لذلك تُراجع أقواله على ضوء النصوص المصرية والآثار المعاصرة."},{"statement":"فتح فك رموز الكتابة المصرية الطريق إلى قراءة نصوص المصريين أنفسهم.","answer":true,"explanation":"أصبح الباحث قادرًا على فحص أسماء الملوك والحوادث المدونة على المعابد والبرديات بدل الاعتماد الكامل على روايات لاحقة."},{"statement":"تخلو الآثار المصرية من المصادر المكتوبة، ولذلك لا تفيد في دراسة التاريخ السياسي.","answer":false,"explanation":"تضم الآثار نقوشًا وبرديات وسجلات مكتوبة، وهي شواهد أساسية على الملوك والأحداث والإدارة."},{"statement":"يساعد حجر باليرمو في دراسة الحوليات والأخبار الملكية القديمة.","answer":true,"explanation":"يعرض الحجر تسجيلات حولية مرتبطة بعصور مبكرة، فيكمل القوائم الملكية وغيرها من الأدلة."},{"statement":"تتفق جميع القوائم الملكية في الأسماء والترتيب ولا تعاني أي نقص.","answer":false,"explanation":"تختلف القوائم في ما حفظته من أسماء وفي حالة أجزائها؛ والمقارنة بينها تكشف الفراغات والاختلافات بدل إلغائها."}],"essay":[{"question":"بيّن أهمية فك رموز اللغة المصرية القديمة لدراسة التاريخ المصري.","answer":"أتاح فك الرموز قراءة النصوص المنقوشة على الآثار والبرديات وترجمتها، فصار بالإمكان فحص شهادات مصرية أصلية قريبة من الأحداث بدل الاعتماد على الروايات المتأخرة وحدها."},{"question":"اذكر أهم القوائم الملكية المصرية، ووضح فائدة المقارنة بينها.","answer":"من أهم الشواهد حجر باليرمو، وقوائم الكرنك وأبيدوس وسقارة، وبردية تورين. تساعد المقارنة بينها وبين الآثار الأخرى في تتبع أسماء الملوك وتسلسل العهود وكشف مواضع النقص والاختلاف."},{"question":"قارن قيمة الآثار المصرية بروايات المؤرخين الكلاسيكيين عند كتابة التاريخ.","answer":"الآثار والنصوص المصرية قد تكون معاصرة للأحداث وتكشف الأسماء والمنشآت والإدارة من داخل المجتمع المصري. أما المؤرخون الكلاسيكيون فيضيفون روايات وشهادات لاحقة، لكنها تحتاج فحصًا نقديًا ومقارنتها بالأدلة الأصلية."},{"question":"كيف يستخدم الباحث أكثر من قائمة ملكية لإعادة بناء تسلسل حكام مصر القديمة؟","answer":"يقارن أسماء الملوك وترتيبهم في حجر باليرمو وقوائم الكرنك وأبيدوس وسقارة وبردية تورين، ثم يطابقها بالنقوش والآثار المؤرخة. اختلاف القوائم أو نقصها سبب للمقارنة لا للاعتماد على واحدة وحدها."}]},"history/lecture-03":{"source":"تاريخ مصر القديم، المحاضرة 3 (ملف المحاضرة المعتمد)، صفحات 22–32 من الملزمة؛ PDF 11 صفحة","trueFalse":[{"statement":"تمر حضارات نقادة بثلاث مراحل متعاقبة.","answer":true,"explanation":"تأتي نقادة الأولى، ثم الثانية، ثم الثالثة ضمن تطور عصر ما قبل الأسرات، ولكل مرحلة شواهدها الحضارية."},{"statement":"تسبق نقادة الثالثة نقادة الأولى زمنيًا.","answer":false,"explanation":"الترتيب الزمني هو نقادة الأولى، ثم الثانية، ثم الثالثة؛ وعكسه يخل بتسلسل تطور ما قبل الأسرات."},{"statement":"اعتمد الإنسان في العصر الحجري القديم أساسًا على الصيد وجمع موارد البيئة.","answer":true,"explanation":"سبق الاقتصاد القائم على الصيد والجمع الاستقرار الزراعي الذي ميز العصر الحجري الحديث."},{"statement":"تنتمي حضارة الفيوم (أ) إلى العصر النحاسي وحده.","answer":false,"explanation":"تُعرض الفيوم (أ) ضمن مجتمعات العصر الحجري الحديث المرتبطة ببدايات الزراعة والاستقرار."},{"statement":"ترتبط حضارة البداري بمنطقة أسيوط وبدايات العصر النحاسي.","answer":true,"explanation":"تعد البداري من شواهد صعيد مصر في المرحلة السابقة لتطور حضارات نقادة."},{"statement":"العصر الحجري الحديث أقدم من العصر الحجري القديم.","answer":false,"explanation":"العصر الحجري القديم يسبق الحديث؛ وفي الحديث تعاظمت الزراعة والاستقرار وتربية الحيوان."}],"essay":[{"question":"رتب مراحل نقادة الثلاث، واذكر أسماءها البديلة.","answer":"الترتيب هو نقادة الأولى (العَمرة)، ثم نقادة الثانية (جرزة)، ثم نقادة الثالثة (السماينة). تنتمي هذه المراحل إلى عصر ما قبل الأسرات وتسبق قيام الدولة الموحدة."},{"question":"وضح موضع حضارتي دير تاسا والبداري بين حضارات ما قبل الأسرات.","answer":"تندرج دير تاسا ضمن المراحل المبكرة قبل الأسرات، وتظهر البداري في صعيد مصر ضمن بدايات العصر النحاسي. سبقتا تطور نقادة الأولى والثانية والثالثة."},{"question":"ما التحول الاقتصادي والاجتماعي الذي يميز العصر الحجري الحديث عن العصر الحجري القديم؟","answer":"في القديم غلب الصيد وجمع الغذاء والحركة بحثًا عن الموارد. وفي الحديث توسعت الزراعة وتربية الحيوان والاستقرار في القرى، فظهرت أدوات ونظم تلائم الإنتاج."},{"question":"رتب حضارات دير تاسا والبداري ونقادة في سياق ما قبل الأسرات، مع توضيح أهمية ترتيبها.","answer":"تظهر دير تاسا والبداري في المراحل المبكرة التي تسبق نقادة، ثم تتعاقب نقادة الأولى والثانية والثالثة. يفيد الترتيب في تتبع تطور الصناعات والعادات الاجتماعية حتى مرحلة قيام الدولة."}]},"history/lecture-04":{"source":"تاريخ مصر القديم، المحاضرة 4 (ملف المحاضرة المعتمد)، صفحات 33–45 من الملزمة؛ PDF 13 صفحة","trueFalse":[{"statement":"تمثل لوحة نعرمر شاهدًا أثريًا مهمًا عند دراسة توحيد القطرين.","answer":true,"explanation":"تصور اللوحة الملك ورموز السيادة على الوجهين، ولذلك تُستخدم مع الأدلة الأخرى لفهم نشأة السلطة المركزية."},{"statement":"المقبرة الرمزية والمقبرة الحقيقية اسمان لموضع دفن واحد بالضرورة.","answer":false,"explanation":"المقبرة الحقيقية تضم موضع الدفن، بينما قد تكون المقبرة الرمزية منشأة تذكارية مرتبطة بالملك من دون دفن الجثمان فيها."},{"statement":"يرتبط لقب «نيسو بيتي» بملك مصر العليا والسفلى.","answer":true,"explanation":"يجمع اللقب رمزي الصعيد والدلتا، ويعبر عن سلطة الملك على القطرين."},{"statement":"ينتمي الملك جر إلى الأسرة الثانية التي أعقبت حتب سخموي.","answer":false,"explanation":"جر من ملوك الأسرة الأولى؛ أما حتب سخموي فيرتبط ببداية الأسرة الثانية."},{"statement":"تعد لوحة نعرمر وحدها دليلًا كافيًا لإثبات كل تفاصيل عملية التوحيد الطويلة.","answer":false,"explanation":"اللوحة شاهد محوري، لكن توحيد البلاد كان عملية تاريخية تُدرس مع شواهد أثرية ونصوص أخرى."},{"statement":"يرتبط الملك خع سخموي بأواخر الأسرة الثانية والانتقال إلى عصر الدولة القديمة.","answer":true,"explanation":"يأتي خع سخموي في نهاية العصر العتيق تقريبًا، وتصل مرحلة حكمه بين الأسرة الثانية وبدايات الأسرة الثالثة."}],"essay":[{"question":"اشرح كيف يمكن استخدام لوحة نعرمر في عرض قصة توحيد القطرين للسائح.","answer":"يبدأ الشرح بتحديد اللوحة كشاهد أثري من العصر العتيق، ثم يربط مشاهدها ورموزها بموضوع السلطة الملكية وتوحيد القطرين، مع التمييز بين ما تظهره القطعة نفسها والتفسير التاريخي لها."},{"question":"وضّح الفرق بين المقبرة الحقيقية والمقبرة الرمزية، ولماذا يهم هذا الفرق في شرح آثار العصر العتيق.","answer":"المقبرة الحقيقية هي موضع الدفن، أما المقبرة الرمزية فهي منشأة تذكارية لا يلزم أن تضم الجثمان. يساعد التمييز في فهم تعدد المنشآت المنسوبة إلى الملك وتقديم تفسير دقيق للزائر."},{"question":"اشرح كيف تطورت محاولات توحيد الدلتا والصعيد قبل قيام الأسرة الأولى.","answer":"لم تكن الوحدة حدثًا معزولًا؛ سبقتها اتحادات وصراعات وانقسامات بين أقاليم الشمال والجنوب. انتهى المسار بظهور سلطة مركزية تربط القطرين في بدايات العصر العتيق."},{"question":"ما دلالة لوحة نعرمر ولقب «نيسو بيتي» في شرح فكرة الملكية الموحدة؟","answer":"تقدم اللوحة صورًا ورموزًا للملك وسيادته، بينما يجمع لقب «نيسو بيتي» رمزي مصر العليا والسفلى. يُستدل بهما على فكرة حكم القطرين، مع إبقاء التفسير مرتبطًا بسائر الأدلة الأثرية."}]},"islamic-history/lecture-01":{"source":"د. رمضان أحمد محمد السيد، التاريخ والحضارة الإسلامية 2026–2027، المحاضرة رقم (1)، PDF 14 صفحة","trueFalse":[{"statement":"أسهم مجمع خلقيدونية سنة 451م في تعميق الخلاف الديني بمصر البيزنطية.","answer":true,"explanation":"أدى الخلاف حول العقيدة بعد المجمع إلى توتر بين الكنيسة المصرية والسلطة الإمبراطورية، واتسعت آثاره إلى السياسة والمجتمع."},{"statement":"اقتصر الخلاف المذهبي في مصر البيزنطية على مسائل لاهوتية بلا توتر سياسي.","answer":false,"explanation":"اختلط النزاع الديني بعلاقة المصريين بالسلطة البيزنطية، فأصبح الخلاف علامة على توتر سياسي واجتماعي أيضًا."},{"statement":"كانت مصر مصدرًا مهمًا للقمح الذي احتاجته القسطنطينية.","answer":true,"explanation":"جعل إنتاج الغلال مصر ذات وزن اقتصادي كبير للإمبراطورية، ولذلك اهتمت السلطة بجباية المحصول والضرائب."},{"statement":"حسّن نظام الحماية وضع الفلاحين دائمًا بإلغاء الأعباء الضريبية عنهم.","answer":false,"explanation":"لجأ بعض الفلاحين إلى حماية أصحاب النفوذ هربًا من التعسف، لكن ذلك قد زاد تبعيتهم ووسع علاقات الإقطاع."},{"statement":"كان حصن بابليون من المراكز العسكرية المهمة في مصر البيزنطية.","answer":true,"explanation":"مثّل الحصن موضعًا دفاعيًا رئيسيًا عند مدخل مصر، فصار هدفًا حاسمًا أثناء الفتح الإسلامي."},{"statement":"اتسم الحكم البيزنطي بالمساواة الاجتماعية الكاملة بين عامة المصريين والفئات الأجنبية الحاكمة.","answer":false,"explanation":"تمتعت فئات مرتبطة بالسلطة بامتيازات، بينما عانى كثير من المصريين من الأعباء والقيود الاجتماعية."}],"essay":[{"question":"اشرح أحوال مصر الدينية قبيل الفتح الإسلامي وعلاقة مجمع خلقيدونية بالتوتر الداخلي.","answer":"انتشرت المسيحية في مصر وتغير وضعها الرسمي داخل الإمبراطورية، ثم تعمق الخلاف المذهبي بعد مجمع خلقيدونية سنة 451م. تجاوز أثر الخلاف العقيدة إلى التوتر بين السلطة البيزنطية وقطاع من سكان مصر."},{"question":"بيّن لماذا كانت مصر ذات أهمية اقتصادية للإمبراطورية البيزنطية.","answer":"وفر محصول القمح المصري جزءًا مهمًا من غذاء القسطنطينية، وكانت شحنات الغلال والجباية سببًا رئيسيًا لاهتمام السلطة البيزنطية بالبلاد."},{"question":"كيف أثرت الضرائب ونظام الحماية في حياة الفلاح المصري أواخر العصر البيزنطي؟","answer":"فرضت الجباية أعباء ثقيلة على الزراع، فلجأ بعضهم إلى حماية كبار الملاك أو ذوي النفوذ. خففت الحماية الخطر المباشر أحيانًا، لكنها ربطت الفلاح بالأرض وبصاحب الحماية وأسهمت في نمو التبعية الإقطاعية."},{"question":"لماذا كان حصن بابليون مهمًا في دفاع البيزنطيين عن مصر؟","answer":"كان حصنًا عسكريًا محصنًا في موضع استراتيجي بمصر القديمة، يسيطر على طريق الدخول نحو الوادي. لذلك كان إخضاعه خطوة حاسمة قبل تثبيت السيطرة على البلاد."}]},"islamic-history/lecture-02":{"source":"د. رمضان أحمد محمد السيد، التاريخ والحضارة الإسلامية 2026–2027، المحاضرة رقم (2)، PDF 11 صفحة","trueFalse":[{"statement":"سبق حصار حصن بابليون صلح الإسكندرية.","answer":true,"explanation":"تقدم الجيش نحو الداخل وحاصر بابليون أولًا، ثم انتهت مرحلة لاحقة بالتفاوض على تسليم الإسكندرية."},{"statement":"لم يحاول البيزنطيون استرداد الإسكندرية بعد الفتح.","answer":false,"explanation":"جرت محاولة بيزنطية بقيادة مانويل لاسترداد المدينة، لكنها لم تُنه السيطرة الإسلامية على مصر."},{"statement":"كانت الفرما من المحطات الأولى في طريق جيش عمرو بن العاص إلى مصر.","answer":true,"explanation":"تقع الفرما على المدخل الشرقي، ويمر بها الطريق القادم من الشام إلى أرض مصر."},{"statement":"نص صلح الإسكندرية على بقاء الحامية البيزنطية بلا جلاء من المدينة.","answer":false,"explanation":"نظم الصلح جلاء الحامية البيزنطية وتسليم المدينة، إلى جانب بنود تخص أمن السكان وعبادتهم."},{"statement":"نص صلح الإسكندرية على حماية كنائس المسيحيين وعدم التدخل في شؤونهم الدينية.","answer":true,"explanation":"أقر أحد شروط الصلح بقاء الكنائس وحرية الممارسة الدينية، وهو بند مهم لفهم وضع السكان بعد الفتح."},{"statement":"أدت محاولة مانويل إلى عودة الحكم البيزنطي الدائم لمصر.","answer":false,"explanation":"كانت محاولة استرداد عسكرية لاحقة، ولم تنجح في إعادة السيطرة البيزنطية الدائمة."}],"essay":[{"question":"تتبع المراحل الأساسية لفتح مصر من مسار جيش عمرو بن العاص إلى صلح الإسكندرية.","answer":"دخل جيش عمرو بن العاص من الجهة الشرقية واتبع طريقًا يستفيد من حافة الصحراء. مر بمحطات مثل الفرما، ثم حاصر حصن بابليون، وتقدم إلى الإسكندرية حيث جرى الصلح. حاول البيزنطيون استعادة الإسكندرية لاحقًا دون تثبيت حكمهم."},{"question":"لماذا كان سقوط حصن بابليون خطوة مهمة في فتح مصر؟","answer":"كان الحصن معقلًا بيزنطيًا محصنًا عند طريق الدخول إلى الوادي. استغرق حصاره وقتًا وجهدًا، وفتح سقوطه الطريق إلى تثبيت السيطرة على الداخل ثم التقدم نحو تسوية الإسكندرية."},{"question":"اذكر أهم الدوافع الاستراتيجية التي جعلت مصر هدفًا للفتح بعد الشام.","answer":"كان تأمين فتوحات الشام وفلسطين يتطلب منع البيزنطيين من استخدام مصر قاعدة للهجوم، مع حماية طرق التجارة والاستفادة من موقع مصر ومواردها. أثّر أيضًا ضعف الحكم البيزنطي والتوتر مع السكان في تقدير الموقف."},{"question":"ما البنود التي تبرز أهمية صلح الإسكندرية سياسيًا ودينيًا؟","answer":"نظّم الصلح جلاء الحامية البيزنطية وتسليم المدينة، وضم شروطًا تتعلق بأمن السكان وأموالهم وحماية الكنائس وعدم التدخل في شؤون المسيحيين الدينية. لذلك مثّل انتقالًا من الحصار إلى حكم جديد بشروط معلنة."}]},"islamic-history/lecture-03":{"source":"د. رمضان أحمد محمد السيد، التاريخ والحضارة الإسلامية 2026–2027، المحاضرة رقم (3)، PDF 16 صفحة","trueFalse":[{"statement":"عاونت الشرطة والقضاء والبريد الوالي في إدارة مصر الإسلامية.","answer":true,"explanation":"اختصت الشرطة بالأمن، والقضاء بالفصل في الخصومات، والبريد بنقل الأخبار والمراسلات وربط الإدارة بمركز الحكم."},{"statement":"كانت العسكر العاصمة الإسلامية الأولى لمصر قبل الفسطاط.","answer":false,"explanation":"تأسست الفسطاط بعد الفتح لتكون مركز الحكم الأول، أما العسكر فنشأت في العصر العباسي اللاحق."},{"statement":"ارتبط تأسيس الفسطاط باستقرار المسلمين في مصر بعد الفتح.","answer":true,"explanation":"نشأت الفسطاط مركزًا للإدارة والجيش، ثم ارتبط بها جامع عمرو بن العاص."},{"statement":"كانت معركة ذات الصواري معركة برية دارت حول حصن بابليون.","answer":false,"explanation":"ذات الصواري معركة بحرية بين الأسطولين الإسلامي والبيزنطي سنة 34 هـ / 655م."},{"statement":"بدأ تعريب الدواوين في مصر في العصر الأموي بعد الفتح بمدة.","answer":true,"explanation":"لم تتحول السجلات الإدارية إلى العربية فور دخول المسلمين؛ جاء التعريب في مرحلة أموية لاحقة."},{"statement":"اقتصر عمل صاحب البريد على شؤون العبادة ولم يشمل نقل أخبار الولاية.","answer":false,"explanation":"نقل صاحب البريد المراسلات والأخبار إلى مركز الحكم، فكان أداة اتصال وإبلاغ إداري."}],"essay":[{"question":"اشرح دور الوالي والمؤسسات المعاونة له في إدارة مصر خلال عصر الولاة.","answer":"تولى الوالي قيادة الحكم وإدارة شؤون الولاية، واستمر استخدام بعض النظم القائمة لتسيير العمل. عاونته الشرطة في الأمن، والقضاء في الفصل في النزاعات، والبريد في نقل الأخبار والمراسلات."},{"question":"وضح تسلسل ظهور الفسطاط والعسكر وموقع كل منهما في تاريخ مصر الإسلامية.","answer":"نشأت الفسطاط بعد الفتح لتكون مركزًا للحكم واستقرار الجند. أما العسكر فظهرت في العصر العباسي بعد سقوط الدولة الأموية، فصارت مركزًا جديدًا للسلطة."},{"question":"اشرح دور الفسطاط وجامع عمرو بن العاص في نشأة مصر الإسلامية.","answer":"صارت الفسطاط مركزًا للإدارة واستقرار الجند بعد الفتح، وقام فيها جامع عمرو بن العاص مركزًا للصلاة والحياة العامة. ارتبط نشوء المدينة والجامع بتثبيت الحكم الإسلامي وتنظيم المجتمع الجديد."},{"question":"ما أهمية معركة ذات الصواري وتعريب الدواوين في تطور الدولة الإسلامية بمصر؟","answer":"أظهرت ذات الصواري قدرة الأسطول الإسلامي على مواجهة البيزنطيين بحرًا وحماية السواحل. أما تعريب الدواوين فحوّل لغة السجلات والإدارة إلى العربية في مرحلة أموية لاحقة، وأسهم في توحيد أدوات الحكم."}]},"graeco-roman/lecture-01":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 8–14; Greek Civilization slides 6, 7, 12–14","trueFalse":[{"statement":"يعد العصر الهيلينستي إحدى مراحل التاريخ اليوناني.","answer":true,"explanation":"بدأ العصر الهيلينستي بعد وفاة الإسكندر سنة 323 ق.م، وانتشرت فيه الثقافة اليونانية في مصر ومناطق الشرق."},{"statement":"جاء العصر الكلاسيكي بعد العصر الهيلينستي.","answer":false,"explanation":"سبق العصر الكلاسيكي توسع مقدونيا، ثم بدأ العصر الهيلينستي بعد وفاة الإسكندر."},{"statement":"تعود البداية التقليدية للألعاب الأولمبية إلى سنة 776 ق.م.","answer":true,"explanation":"كانت الألعاب من الروابط الثقافية بين المدن اليونانية المستقلة، إلى جانب اللغة والأساطير المشتركة."},{"statement":"يمتاز تاج العمود الدوري بالبساطة مقارنة بتاج العمود الكورنثي.","answer":true,"explanation":"التاج الدوري بسيط، أما الكورنثي فيتميز بزخارف أوراق الأكانثوس."},{"statement":"تزخرف أوراق الأكانثوس تاج العمود الأيوني لا الكورنثي.","answer":false,"explanation":"الأكانثوس سمة التاج الكورنثي؛ ويتميز الأيوني باللفائف الحلزونية."},{"statement":"كانت المدن اليونانية القديمة كلها تابعة لحكومة مركزية واحدة.","answer":false,"explanation":"كانت «البوليس» مدينة دولة مستقلة بحكمها وأراضيها، رغم اشتراك المدن في عناصر ثقافية."}],"essay":[{"question":"رتب الحقب الأربع الكبرى للتاريخ اليوناني.","answer":"عصر الظلمات، ثم العصر العتيق أو الآركي، ثم العصر الكلاسيكي أو الهيليني، ثم العصر الهيلينستي."},{"question":"ما الفرق بين العصر الهيليني والعصر الهيلينستي؟","answer":"يشير الهيليني هنا إلى العصر الكلاسيكي للمدن اليونانية المستقلة. أما الهيلينستي فيبدأ بعد وفاة الإسكندر، حين انتشرت الثقافة اليونانية في مصر والشرق ضمن ممالك خلفائه."},{"question":"ما العناصر التي أسهمت في الوحدة الثقافية للمدن اليونانية رغم استقلالها السياسي؟","answer":"تُبرز شرائح الدكتورة اللغة والأساطير المشتركة والألعاب الأولمبية. وكانت كل بوليس مدينة دولة مستقلة بنظامها السياسي، لكن هذه العناصر جمعت اليونانيين ثقافيًا."},{"question":"قارن بين الطرز الدوري والأيوني والكورنثي من حيث شكل التاج.","answer":"الدوري تاجه بسيط قليل الزخرفة وعموده متين. الأيوني أنحف، وتظهر في تاجه لفائف حلزونية. الكورنثي أكثر زخرفة، ويظهر فيه نبات الأكانثوس."}]},"graeco-roman/lecture-02":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 15–17","trueFalse":[{"statement":"طور فيليب الثاني تشكيل الفيلانكس ضمن إصلاح الجيش المقدوني.","answer":true,"explanation":"ساعد تنظيم صفوف الفيلانكس وتسليحها على زيادة قوة الجيش، فصار أداة أساسية في صعود مقدونيا."},{"statement":"توفي فيليب الثاني بعد حكم ابنه الإسكندر لمصر.","answer":false,"explanation":"اغتيل فيليب سنة 336 ق.م، ثم تولى الإسكندر الحكم ودخل مصر سنة 332 ق.م."},{"statement":"قضى فيليب الثاني فترة رهينة في طيبة اليونانية قبل حكم مقدونيا.","answer":true,"explanation":"أتاحت له تجربة طيبة الاطلاع على أساليب الحرب اليونانية التي أفاد منها في تنظيم جيشه."},{"statement":"كان أرسطو معلم فيليب الثاني الخاص في طفولته.","answer":false,"explanation":"ارتبط أرسطو بتعليم الإسكندر ابن فيليب، لا بتعليم فيليب في طفولته."},{"statement":"جاءت أوليمبياس زوجة فيليب الثاني من إبيروس.","answer":true,"explanation":"كان زواج فيليب من أميرة إبيروس جزءًا من شبكة علاقاته السياسية والأسرية، وهي أم الإسكندر."},{"statement":"اعتمد فيليب الثاني على القتال وحده من دون سياسة أو تحالفات لبسط نفوذه على اليونان.","answer":false,"explanation":"جمع بين القوة العسكرية والوسائل السياسية والتحالفات في سعيه إلى زعامة المدن اليونانية."}],"essay":[{"question":"اشرح أهمية الفيلانكس في إصلاحات فيليب الثاني العسكرية.","answer":"الفيلانكس تشكيل قتالي منظم طوّره فيليب الثاني ضمن إصلاح جيشه. زاد الانضباط والتنسيق بين صفوف المقاتلين، فدعم قدرة مقدونيا على فرض نفوذها."},{"question":"كيف مهّد فيليب الثاني لصعود مقدونيا في بلاد اليونان؟","answer":"جمع فيليب الثاني بين جيش منظم يعتمد على الفيلانكس ووسائل سياسية وتحالفات للسيطرة على المدن اليونانية. اغتيل سنة 336 ق.م، فانتقل الحكم إلى ابنه الإسكندر."},{"question":"كيف أفادت خبرة فيليب الثاني في طيبة إصلاح الجيش المقدوني؟","answer":"تعرف فيليب في طيبة إلى التنظيم العسكري اليوناني، ثم طور جيش مقدونيا والفيلانكس. ساعده ذلك على بناء قوة منظمة تدعم مشروعه السياسي في بلاد اليونان."},{"question":"اذكر الأدوات العسكرية والسياسية التي استخدمها فيليب الثاني لفرض نفوذ مقدونيا.","answer":"استند إلى جيش منظم وتشكيل الفيلانكس، كما استخدم التحالفات والوسائل السياسية لتوسيع نفوذه بين المدن. ثم انتهى حكمه باغتياله سنة 336 ق.م، وتولى الإسكندر من بعده."}]},"graeco-roman/lecture-03":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 18–26","trueFalse":[{"statement":"توفي الإسكندر الأكبر في بابل سنة 323 ق.م.","answer":true,"explanation":"أنهت وفاته مشروعه السياسي المباشر، وبدأ قادته بعد ذلك التنافس على إدارة الإمبراطورية وتقسيمها."},{"statement":"لا توجد شواهد أثرية مرتبطة بالإسكندر في مصر.","answer":false,"explanation":"توجد له مقصورة في معبد الأقصر ونقوش وعملات تربطه بالتصور الملكي والديني المصري."},{"statement":"دخل الإسكندر مصر سنة 332 ق.م.","answer":true,"explanation":"دخلها بعد حملاته ضد الفرس، ثم اتخذ خطوات لإظهار شرعية حكمه عند المصريين."},{"statement":"تأسست الإسكندرية قبل وصول الإسكندر إلى مصر.","answer":false,"explanation":"ارتبط تأسيس المدينة بزيارة الإسكندر لمصر واختياره موقعها على ساحل البحر المتوسط."},{"statement":"ارتبطت رحلة الإسكندر إلى واحة سيوة بمعبد آمون.","answer":true,"explanation":"كانت زيارة المعبد جزءًا من بناء صورته الدينية والملكية في مصر."},{"statement":"كان جسر الهيبتاستاديون يفصل جزيرة فاروس عن بر الإسكندرية بدل أن يصل بينهما.","answer":false,"explanation":"وصل الجسر جزيرة فاروس بالبر، وأسهم في تشكيل الموانئ والمدينة."}],"essay":[{"question":"اشرح عوامل اختيار موقع الإسكندرية وأهمية الموانئ وجسر الهيبتاستاديون في تخطيطها.","answer":"اختير موقع الإسكندرية على ساحل البحر المتوسط ليخدم الاتصال البحري. وصل جسر الهيبتاستاديون جزيرة فاروس بالبر وأسهم في تشكيل الموانئ وتخطيط المدينة."},{"question":"اذكر شاهدين أثريين مرتبطين بالإسكندر في مصر، وبيّن فائدة الشواهد للمرشد السياحي.","answer":"من الشواهد مقصورة الإسكندر في معبد الأقصر، ومناظر مرتبطة بآمون في طيبة، وعملة تصور قرني كبش آمون. تربط هذه الآثار صورته الملكية والدينية بأشياء مادية يمكن فحصها."},{"question":"كيف جمع الإسكندر بين الشرعية السياسية والدينية بعد دخوله مصر؟","answer":"دخل مصر سنة 332 ق.م، وتوج في منف وفق الرموز الملكية المصرية، ثم زار معبد آمون في واحة سيوة. ساعده الجمع بين هذه الخطوات على تقديم نفسه حاكمًا مقبولًا في السياق المصري."},{"question":"ما النتائج السياسية لوفاة الإسكندر في بابل سنة 323 ق.م؟","answer":"ترك الإسكندر إمبراطورية واسعة بلا انتقال بسيط للسلطة، فاجتمع القادة وتنافسوا على الأقاليم. انتهى الصراع إلى ممالك خلفاء الإسكندر، ومنها المملكة البطلمية في مصر."}]},"graeco-roman/lecture-04":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 27–37; Ptolemaic Dynasty slide 1","trueFalse":[{"statement":"ارتبط الموسيون ومكتبة الإسكندرية بمشروع بطليموس الأول العلمي في العاصمة.","answer":true,"explanation":"جذبت المؤسستان العلماء وجمعتا المعرفة، فدعمتا مكانة الإسكندرية مركزًا ثقافيًا وسياسيًا."},{"statement":"ظهرت عبادة سيرابيس خارج سياق العصر البطلمي تمامًا.","answer":false,"explanation":"ارتبطت عبادة سيرابيس بسياسة البطالمة الدينية في الإسكندرية، وكان السرابيوم من أهم مواقعها."},{"statement":"حكم البطالمة مصر بعد تقسيم إمبراطورية الإسكندر، بينما حكم السلوقيون الشام وبلاد الرافدين.","answer":true,"explanation":"تقاسمت أسر خلفاء الإسكندر الأقاليم؛ فاستقر حكم البطالمة بمصر والسلوقيين بمناطق شرقية واسعة."},{"statement":"كانت الإسكندرية عاصمة مصر في عهد البطالمة.","answer":true,"explanation":"صارت الإسكندرية مركز الحكم والثقافة، وكانت اليونانية لغة الدولة في الإدارة البطلمية."},{"statement":"كانت عبادة سيرابيس عبادة يونانية خالصة لا صلة لها بالعناصر المصرية.","answer":false,"explanation":"جمعت صورة سيرابيس عناصر من تقاليد مصرية ويونانية، لذلك تفيد في فهم التداخل الديني البطلمي."},{"statement":"كانت طيبة عاصمة بطليموس الأول بدل الإسكندرية.","answer":false,"explanation":"اتخذ البطالمة الإسكندرية عاصمة، بينما بقيت طيبة مركزًا دينيًا مهمًا في الصعيد."}],"essay":[{"question":"اشرح دور الموسيون ومكتبة الإسكندرية في مشروع بطليموس الأول.","answer":"كان الموسيون والمكتبة مؤسستين علميتين في الإسكندرية لجمع المعرفة وجذب العلماء. دعمتا مكانة العاصمة الجديدة مركزًا ثقافيًا وسياسيًا في العالم الهيلينستي."},{"question":"ما أهمية عبادة سيرابيس والسرابيوم في شرح العصر البطلمي للزوار؟","answer":"ارتبطت عبادة سيرابيس والسرابيوم بالحياة الدينية في الإسكندرية البطلمية. تجمع صور الإله عناصر مصرية ويونانية، ويساعد تمثاله وموقع المعبد على شرح هذا التداخل الثقافي."},{"question":"ضع البطالمة ضمن ممالك خلفاء الإسكندر، واذكر عاصمة مصر ولغة الحكم في عهدهم.","answer":"بعد وفاة الإسكندر توزعت إمبراطوريته: حكم البطالمة مصر، والسلوقيون بلاد الرافدين والشام، والأتاليديون بيرجامون. أصبحت الإسكندرية عاصمة مصر وصارت اليونانية لغة الحكم، بحسب الشريحة الأولى من عرض الأسرة البطلمية."},{"question":"كيف ساعدت الموسيون والمكتبة والإسكندرية بطليموس الأول في تثبيت حكمه؟","answer":"جعل من الإسكندرية عاصمة سياسية ومركزًا للمعرفة. جذب الموسيون والمكتبة العلماء والنصوص، ورسخا مكانة الدولة الجديدة ضمن العالم الهيلينستي."}]},"graeco-roman/lecture-05":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 38–43","trueFalse":[{"statement":"ارتبط عهد بطليموس الثاني باستصلاح الفيوم وإكمال فنار الإسكندرية.","answer":true,"explanation":"جمعت سياسته بين مشروعات زراعية توسع الإنتاج ومشروعات بحرية وعمرانية تعزز دور العاصمة."},{"statement":"لم يترك عهد بطليموس الثاني شواهد في معابد مصرية.","answer":false,"explanation":"تحفظ فيلة والكرنك نقوشًا وآثارًا بطلمية، إلى جانب الشواهد اليونانية في الإسكندرية."},{"statement":"ارتبط اسم أرسينوي الثانية بزواجها من أخيها بطليموس الثاني وتقديسها بعد ذلك.","answer":true,"explanation":"كان زواجهما من أبرز سمات الأسرة البطلمية في هذا العصر، وظهرت للملكة مكانة دينية رسمية."},{"statement":"كانت الترجمة السبعينية ترجمة للنصوص العبرية إلى اللاتينية.","answer":false,"explanation":"الترجمة السبعينية نقلت نصوصًا دينية عبرية إلى اليونانية في بيئة الإسكندرية."},{"statement":"كتب مانيتون تاريخًا لمصر عُرف باسم «أجيبتياكا».","answer":true,"explanation":"جمع مانيتون سردًا لتاريخ مصر في العصر البطلمي، فصار مرجعًا مهمًا عند دراسة الأسرات."},{"statement":"نُفيت أرسينوي الثانية إلى قفط بعد طلاقها من بطليموس الثاني.","answer":false,"explanation":"التي نُفيت إلى قفط هي أرسينوي الأولى؛ أما أرسينوي الثانية فصارت زوجة بطليموس الثاني ومُنحت مكانة دينية."}],"essay":[{"question":"بين أهم أوجه النشاط الاقتصادي والعمراني في عهد بطليموس الثاني.","answer":"شملت سياسة بطليموس الثاني تنظيم المال والموارد واستصلاح أراضي الفيوم، وإكمال فنار الإسكندرية. ظهرت رعايته أيضًا في معابد مصرية ونقوشها."},{"question":"كيف توظف الشواهد الأثرية فيلة والكرنك في شرح عصر بطليموس الثاني؟","answer":"تظهر نقوش فيلة وبوابة الكرنك حضور الملك والملكة في المعابد المصرية. يساعد وصف موضع الأثر وشكله ثم ربطه بسياقه الديني والسياسي على شرح استمرار تقاليد الملكية المصرية في العصر البطلمي."},{"question":"ما مظاهر رعاية المعرفة في الإسكندرية خلال عهد بطليموس الثاني؟","answer":"برز توسيع المكتبة، والاهتمام بالترجمة السبعينية إلى اليونانية، وكتابة مانيتون لتاريخ مصر. أسهمت هذه الأعمال في جعل الإسكندرية مركزًا للبحث وجمع النصوص."},{"question":"كيف ارتبط استصلاح الفيوم وإكمال الفنار بالدولة البطلمية في عهد بطليموس الثاني؟","answer":"وسع استصلاح الفيوم الرقعة الزراعية والإنتاج، بينما خدم الفنار الملاحة ومكانة ميناء الإسكندرية. يجمع المشروعان بين تنمية موارد الدولة وتأكيد دور عاصمتها البحري."}]},"graeco-roman/lecture-06":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 44–47","trueFalse":[{"statement":"صدر مرسوم كانوب في عهد بطليموس الثالث سنة 238 ق.م.","answer":true,"explanation":"سجل المرسوم قرارات ملكية ودينية، ومن بينها محاولة إصلاح التقويم بإضافة يوم دوري."},{"statement":"لا علاقة لمرسوم كانوب بإصلاح التقويم.","answer":false,"explanation":"نص المرسوم على محاولة إضافة يوم كل أربع سنوات تقريبًا لمعالجة فرق ربع اليوم، وهي فكرة السنة الكبيسة."},{"statement":"بلغت المملكة البطلمية اتساعًا ونفوذًا كبيرين في عهد بطليموس الثالث.","answer":true,"explanation":"ارتبط عهده بالحرب السورية الثالثة والتقدم شرقًا، وهي من ذرى القوة البطلمية."},{"statement":"انتهت الحرب السورية الثالثة بهزيمة بطليموس الثالث قبل أي تقدم شرقًا.","answer":false,"explanation":"حقق بطليموس الثالث تقدمًا كبيرًا في الحرب السورية الثالثة ووصل نفوذه إلى مناطق شرقية، ومنها بابل."},{"statement":"بدأ تشييد معبد حورس بإدفو في عهد بطليموس الثالث.","answer":true,"explanation":"يرتبط بدء البناء بعام 237 ق.م، وتقدم مناظره شاهدًا على صلة الملوك البطالمة بالمعابد المصرية."},{"statement":"كانت إضافة يوم التقويم في مشروع كانوب تتم في كل سنة دون استثناء.","answer":false,"explanation":"اقترح الإصلاح إضافة يوم دوري بعد أربع سنوات تقريبًا لتعويض أجزاء اليوم المتراكمة."}],"essay":[{"question":"اشرح العلاقة بين مرسوم كانوب وتقويم السنة الكبيسة في عهد بطليموس الثالث.","answer":"صدر مرسوم كانوب سنة 238 ق.م في عهد بطليموس الثالث، واقترح إضافة يوم دوري إلى التقويم لتعويض فرق ربع اليوم المتراكم. ترتبط الفكرة بمبدأ السنة الكبيسة."},{"question":"اذكر شواهد أثرية من عهد بطليموس الثالث.","answer":"منها بدء تشييد معبد حورس بإدفو، وبوابة بطليموس الثالث في الكرنك، وإبريق فيانس مرتبط ببرنيكي الثانية. تربط هذه الشواهد الملكية البطلمية بالمعابد والفنون المصرية."},{"question":"اشرح أسباب بلوغ الدولة البطلمية ذروة نفوذها في عهد بطليموس الثالث.","answer":"تابع بطليموس الثالث سياسة توسع خارجية، وحقق تقدمًا في الحرب السورية الثالثة حتى مناطق شرقية بعيدة. رافق القوة السياسية اهتمام بالشواهد الدينية والعمرانية داخل مصر."},{"question":"ما أهمية معبد إدفو ومرسوم كانوب لفهم سياسة بطليموس الثالث؟","answer":"يرتبط بدء تشييد معبد حورس بإدفو بعهد الملك، مما يوضح رعاية المعابد المصرية. ويكشف مرسوم كانوب سنة 238 ق.م عن قرارات ملكية ودينية ومحاولة إصلاح التقويم بإضافة يوم دوري."}]},"graeco-roman/lecture-07":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 48–51","trueFalse":[{"statement":"وقعت معركة رفح في عهد بطليموس الرابع.","answer":true,"explanation":"انتصر جيشه في رفح سنة 217 ق.م خلال الحرب السورية الرابعة، وكانت من أهم مواجهات البطالمة والسلوقيين."},{"statement":"لم تترك معركة رفح أي أثر في تاريخ المملكة البطلمية.","answer":false,"explanation":"أظهرت رفح قوة الجيش، لكن المرحلة التالية شهدت توترات داخلية وثورات في الصعيد؛ ولذلك تعد نقطة تحول."},{"statement":"دارت معركة رفح سنة 217 ق.م بين البطالمة والسلوقيين.","answer":true,"explanation":"كانت المواجهة جزءًا من الحرب السورية الرابعة على النفوذ في سورية المجوفة."},{"statement":"لم يشارك جنود مصريون في جيش بطليموس الرابع في رفح.","answer":false,"explanation":"شارك مصريون في تشكيلات القتال، وكان دورهم من السمات اللافتة في المعركة."},{"statement":"بدأت اضطرابات طيبة بعد انتصار رفح ضمن أزمة المملكة الداخلية.","answer":true,"explanation":"لم يمنع النصر الخارجي اتساع مشكلات الحكم والاضطراب في صعيد مصر."},{"statement":"كانت أفيال الجيشين المتقابلين في رفح من مصدر واحد ونوع واحد.","answer":false,"explanation":"واجهت الأفيال الأفريقية في الجيش البطلمي أفيالًا آسيوية في جيش السلوقيين، وكان اختلاف المصدر من تفاصيل المعركة."}],"essay":[{"question":"لماذا تعد معركة رفح نقطة تحول في تاريخ البطالمة؟","answer":"كانت رفح سنة 217 ق.م انتصارًا عسكريًا مهمًا لبطليموس الرابع، لكن الفترة التالية شهدت اضطرابات داخلية وثورات في طيبة والصعيد. يوضح التتابع أن النصر الخارجي لم يحل مشكلات الدولة."},{"question":"بيّن كيف يمكن للمرشد الجمع بين السرد العسكري والشواهد الأثرية عند شرح عهد بطليموس الرابع.","answer":"يبدأ الشرح بأطراف معركة رفح ونتيجتها سنة 217 ق.م، ثم ينتقل إلى أثرها السياسي والاضطرابات اللاحقة. وتربط آثار مثل إبريق أرسينوي الثالثة الشخصيات التاريخية بشواهد مادية."},{"question":"كيف أسهم الجنود المصريون في نتيجة معركة رفح؟","answer":"جند بطليموس الرابع قوات مصرية ضمن جيشه في مواجهة السلوقيين، وصمدت تشكيلاتها في المعركة. أظهر ذلك إمكان الاعتماد العسكري على المصريين، مع بقاء التوترات الداخلية بعد النصر."},{"question":"اربط بين الحرب السورية الرابعة ومعركة رفح واضطرابات الصعيد اللاحقة.","answer":"نشبت الحرب على النفوذ في سورية المجوفة، وانتهت معركة رفح سنة 217 ق.م بانتصار بطلمي. لكن الدولة واجهت لاحقًا اضطرابات في طيبة والصعيد، مما يبين أن النجاح العسكري الخارجي لم يحسم أزماتها الداخلية."}]},"graeco-roman/lecture-08":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 52–55","trueFalse":[{"statement":"يرتبط حجر رشيد بمرسوم صدر في منف سنة 196 ق.م في عهد بطليموس الخامس.","answer":true,"explanation":"سُجل المرسوم بخطوط متعددة، فأصبحت المقارنة بين نصوصه ذات قيمة كبيرة في قراءة الكتابة المصرية القديمة."},{"statement":"كُتب نص حجر رشيد بخط واحد فقط.","answer":false,"explanation":"حمل النص ثلاثة خطوط: الهيروغليفية والديموطيقية واليونانية، وهو ما أتاح المقارنة بينها."},{"statement":"تولى بطليموس الخامس الحكم وهو صغير السن وسط صراع على السلطة.","answer":true,"explanation":"استغل رجال البلاط صغر سن الملك، فاشتدت المنافسة والاضطرابات في بداية عهده."},{"statement":"صدر مرسوم حجر رشيد في عهد بطليموس الثالث سنة 238 ق.م.","answer":false,"explanation":"سنة 238 ق.م تخص مرسوم كانوب؛ أما مرسوم حجر رشيد فأصدر في منف سنة 196 ق.م في عهد بطليموس الخامس."},{"statement":"ساعد وجود نص يوناني على حجر رشيد في تفسير صيغتيه المصريتين.","answer":true,"explanation":"أتاحت المقارنة بين النص اليوناني المعروف والخطين المصريين التعرف تدريجيًا إلى قيم العلامات والعبارات."},{"statement":"تسرد نقوش حجر رشيد قصة اكتشاف الحجر في العصر الحديث وحدها.","answer":false,"explanation":"النقش الأصلي مرسوم بطلمي يتعلق بالملك والمؤسسة الدينية؛ أما استخدامه في فك الرموز فحدث بعد قرون."}],"essay":[{"question":"اشرح القيمة التاريخية واللغوية لحجر رشيد في سياق عهد بطليموس الخامس.","answer":"يحمل حجر رشيد مرسومًا صدر في منف سنة 196 ق.م في عهد بطليموس الخامس. سُجل النص بالهيروغليفية والديموطيقية واليونانية، فساعدت المقارنة بين صِيغه على قراءة الكتابة المصرية."},{"question":"ما الفرق بين محتوى مرسوم حجر رشيد وأهمية الحجر اللاحقة في فك الرموز؟","answer":"محتوى النص مرسوم من العصر البطلمي يرتبط بالملك والمؤسسة الدينية. أما قيمته اللاحقة فترتبط بإمكان مقارنة صيغ النص بخطوط مختلفة للمساعدة في قراءة اللغة المصرية القديمة."},{"question":"كيف أثّر صغر سن بطليموس الخامس في السياسة الداخلية عند بداية حكمه؟","answer":"فتح صغر سنه الباب لتنافس رجال البلاط على الوصاية والسلطة، وارتبطت المرحلة باغتيال أرسينوي الثالثة واضطرابات الإسكندرية. أثّر ذلك في استقرار الدولة وقدرتها على مواجهة الضغوط الخارجية."},{"question":"ما الفرق بين الغرض الأصلي من مرسوم حجر رشيد وقيمته العلمية اللاحقة؟","answer":"الغرض الأصلي تسجيل قرارات تكريم الملك بطليموس الخامس الصادرة في منف سنة 196 ق.م. أما قيمته اللاحقة فجاءت من وجود النص باليونانية والديموطيقية والهيروغليفية، مما ساعد على فك رموز الكتابة المصرية."}]},"graeco-roman/lecture-09":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 56–63","trueFalse":[{"statement":"تزايد التدخل الروماني في شؤون مصر خلال عهود البطالمة السادس إلى الثامن.","answer":true,"explanation":"ظهر نفوذ روما في النزاعات بين الملوك وفي تدخل مبعوثها بوبيليوس لإجبار أنطيوخوس على الانسحاب من مصر."},{"statement":"لم تترك عهود البطالمة السادس إلى الثامن شواهد في المعابد المصرية.","answer":false,"explanation":"تضم كوم أمبو وإدفو مناظر ونقوشًا لملوك هذه المرحلة، إلى جانب روايات الصراع السياسي."},{"statement":"أجبر المبعوث الروماني بوبيليوس لايناس أنطيوخوس على اتخاذ قرار الانسحاب من مصر.","answer":true,"explanation":"رسم حوله دائرة في الرمل وطلب جوابًا قبل أن يغادرها؛ وهي صورة واضحة لنفوذ روما المتزايد."},{"statement":"رسم بطليموس السادس دائرة في الرمل ليفرض شروطه على روما.","answer":false,"explanation":"صاحب واقعة الدائرة هو المبعوث الروماني بوبيليوس لايناس، وقد وجه إنذاره إلى الملك السلوقي أنطيوخوس."},{"statement":"ارتبط معبد كوم أمبو المزدوج بالعصر البطلمي في شواهد هذه المرحلة.","answer":true,"explanation":"تظهر فيه آثار ملكية ودينية تساعد على تتبع حضور البطالمة في معابد مصر."},{"statement":"انتهت الصراعات الداخلية تمامًا في عهد بطليموس الثامن فيسكون.","answer":false,"explanation":"ارتبط حكمه بنزاعات عائلية وسياسية واضطرابات مست حياة الإسكندرية ومؤسساتها."}],"essay":[{"question":"اشرح لماذا يصعب فهم عهد البطالمة السادس إلى الثامن بمعزل عن التدخل الروماني.","answer":"تداخلت صراعات البطالمة السادس إلى الثامن مع قوة روما الصاعدة، حتى تدخل مبعوثها بوبيليوس لإلزام أنطيوخوس بالانسحاب من مصر. لهذا يصعب فصل أزمات الحكم الداخلية عن النفوذ الروماني."},{"question":"اذكر شاهدين أثريين من عهود البطالمة السادس إلى الثامن.","answer":"من الشواهد معبد كوم أمبو المزدوج، ونقوش في إدفو تصور بطليموس السادس وكليوباترا الثانية، ومناظر تتعلق ببطليموس الثامن. تكشف هذه الآثار أسماء الحكام وصورهم الرسمية وصلتهم بالمعابد."},{"question":"لماذا تعد واقعة دائرة بوبيليوس في الرمل علامة على تغير ميزان القوى؟","answer":"فرض المبعوث الروماني على أنطيوخوس ردًا فوريًا بشأن انسحابه من مصر، فظهر أن روما قادرة على التأثير في صراع الملوك الهيلينستيين. تكشف الواقعة ضعف استقلال قرار الأطراف المتنازعة أمام القوة الرومانية."},{"question":"اشرح أثر النزاع الأسري في حكم بطليموس الثامن على مصر والإسكندرية.","answer":"تداخلت صراعاته مع كليوباترا الثانية وبقية الأسرة في السياسة الداخلية، وأدت إلى اضطرابات وقمع وخروج بعض أهل العلم من الإسكندرية. يوضح ذلك أثر النزاع على استقرار الدولة ومركزها الثقافي."}]},"graeco-roman/lecture-10":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 64–72","trueFalse":[{"statement":"عرف بطليموس الثاني عشر بلقب «أوليتيس» أي الزمار.","answer":true,"explanation":"ارتبط اللقب بشغفه بالعزف، وصار اسمًا شائعًا له في أخبار أواخر الأسرة البطلمية."},{"statement":"حكم أواخر البطالمة بمعزل تام عن نفوذ روما.","answer":false,"explanation":"سعى بطليموس الثاني عشر إلى شراء اعتراف روما بحكمه، مما يكشف تصاعد تدخلها في شؤون مصر."},{"statement":"استخدم بطليموس العاشر التابوت الذهبي للإسكندر في أزمة مالية تخص مرتزقته.","answer":true,"explanation":"نسب إليه الاستيلاء على الذهب المرتبط بالتابوت لدفع أجور الجنود، وهو ما أثار استنكارًا شديدًا."},{"statement":"لم يقع صراع بين بطليموس التاسع ووالدته كليوباترا الثالثة.","answer":false,"explanation":"كان تدخل كليوباترا الثالثة في تعاقب أبنائها على الحكم جزءًا من أزمات أواخر الأسرة."},{"statement":"قتل بطليموس الحادي عشر برنيكي الثالثة بعد زواجه منها بفترة قصيرة.","answer":true,"explanation":"أثار قتلها غضب أهل الإسكندرية، فهاجموه وأنهوا حكمه القصير."},{"statement":"حكم بطليموس التاسع مصر مرة واحدة متصلة بلا إقصاء أو عودة إلى العرش.","answer":false,"explanation":"تخللت حكم بطليموس التاسع صراعات أسرية وإقصاء، ثم عاد إلى العرش في مرحلة لاحقة."}],"essay":[{"question":"اشرح دلالة سعي بطليموس الثاني عشر للحصول على اعتراف روما بحكمه.","answer":"دفع بطليموس الثاني عشر مبلغًا كبيرًا لقاء اعتراف روما بحكمه. يدل ذلك على تزايد نفوذها السياسي وتراجع قدرة الملك البطلمي على تثبيت عرشه دون دعم خارجي."},{"question":"كيف يظهر بطليموس الثاني عشر في آثار معبد إدفو؟","answer":"يظهر الملك في مناظر على صرح معبد إدفو أمام حورس وحتحور. تدل هذه المناظر على استمرار تمثيل الملك البطلمي داخل الطقوس والرموز الدينية المصرية."},{"question":"كيف أسهمت صراعات بطليموس التاسع والعاشر والحادي عشر في إضعاف الحكم البطلمي؟","answer":"تكرر التنافس العائلي والتدخل في وراثة العرش، وظهرت أزمات مثل الاستيلاء على ذهب تابوت الإسكندر وقتل برنيكي الثالثة. أضعفت هذه الوقائع شرعية الحكم واستقرار العاصمة."},{"question":"ما دلالة دفع بطليموس الثاني عشر المال لروما مقابل الاعتراف بحكمه؟","answer":"يدل على أن بقاء الملك على العرش صار مرتبطًا بتأييد قوة خارجية. أدى الاعتماد المالي والسياسي على روما إلى تقلص استقلال المملكة البطلمية في أواخر عهدها."}]},"graeco-roman/lecture-11":{"source":"Dr. Mervat Maher Amin, History of Graeco-Roman Egypt (1), 2025, pp. 73–76","trueFalse":[{"statement":"تظهر كليوباترا السابعة وابنها قيصرون في نقوش معبد دندرة.","answer":true,"explanation":"قدمت النقوش الأم والابن في إطار الشعائر المصرية، وهي شاهد على استمرار الرموز الملكية المحلية في نهاية العصر البطلمي."},{"statement":"انتهى حكم كليوباترا من دون انتقال مصر إلى الحكم الروماني.","answer":false,"explanation":"أعقبت هزيمة تحالفها مع أنطوني نهاية الحكم البطلمي، ثم ضُمّت مصر إلى سلطة روما سنة 30 ق.م."},{"statement":"أقيم احتفال «تبرعات الإسكندرية» سنة 34 ق.م في زمن أنطوني وكليوباترا.","answer":true,"explanation":"أعلن فيه توزيع ألقاب وأقاليم شرقية على كليوباترا وأبنائها، مما زاد التوتر مع أوكتافيوس."},{"statement":"وقعت معركة أكتيوم البحرية سنة 30 ق.م بعد ضم مصر إلى روما.","answer":false,"explanation":"وقعت أكتيوم سنة 31 ق.م؛ أما نهاية الحكم البطلمي وضم مصر فجاءا سنة 30 ق.م."},{"statement":"ارتبط قيصرون بكليوباترا السابعة ويوليوس قيصر.","answer":true,"explanation":"حمل قيصرون اسم بطليموس الخامس عشر، وظهر مع أمه في نقوش دندرة."},{"statement":"أُعلنت تبرعات الإسكندرية بعد معركة أكتيوم البحرية.","answer":false,"explanation":"أُعلنت التبرعات سنة 34 ق.م، قبل معركة أكتيوم التي وقعت سنة 31 ق.م."}],"essay":[{"question":"اشرح أهمية نقوش دندرة في تقديم كليوباترا السابعة وقيصرون للزائر.","answer":"تُظهر النقوش الملكة وابنها في سياق ديني مصري، وهي شواهد مادية تساعد المرشد على ربط الأسماء المعروفة تاريخيًا بتمثيلهما الرسمي في المعابد المصرية."},{"question":"لخّص العلاقة بين نهاية حكم كليوباترا السابعة وانتقال مصر إلى الحكم الروماني.","answer":"انتهى حكم كليوباترا السابعة بعد هزيمة تحالفها مع أنطوني أمام أوكتافيوس في أكتيوم سنة 31 ق.م. دخلت مصر بعد ذلك في الحكم الروماني سنة 30 ق.م، فانتهت الأسرة البطلمية الحاكمة."},{"question":"كيف أثرت تحالفات كليوباترا السابعة مع قيصر ثم أنطوني في موقع مصر السياسي؟","answer":"ساعد تحالفها مع يوليوس قيصر على تثبيت حكمها، ثم جعلها تحالفها مع مارك أنطوني طرفًا في صراع السلطة الرومانية. زاد احتفال تبرعات الإسكندرية التوتر مع أوكتافيوس حتى المواجهة العسكرية."},{"question":"رتب الأحداث من تبرعات الإسكندرية إلى تحول مصر إلى ولاية رومانية.","answer":"أُعلنت تبرعات الإسكندرية سنة 34 ق.م، ثم تصاعد صراع أنطوني وكليوباترا مع أوكتافيوس. هُزم تحالفهما في أكتيوم سنة 31 ق.م، وانتهى حكم كليوباترا وضُمّت مصر إلى روما سنة 30 ق.م."}]},"modern-history/lecture-01":{"source":"د. حسين السيد، تاريخ مصر الحديث، المحاضرة 1، PDF 11 صفحات","trueFalse":[{"statement":"سبقت معركة مرج دابق سنة 1516م معركة الريدانية سنة 1517م.","answer":true,"explanation":"مهد انتصار العثمانيين في الشام عند مرج دابق لتقدمهم نحو مصر، حيث وقعت الريدانية في العام التالي."},{"statement":"انتهت دولة المماليك في مصر قبل الريدانية ولم يقاوم طومان باي العثمانيين.","answer":false,"explanation":"حاول طومان باي الدفاع عن مصر في الريدانية ثم واصل المقاومة قبل أسره وإعدامه."},{"statement":"سبقت دولة المماليك البحرية دولة المماليك البرجية في مصر.","answer":true,"explanation":"تعاقب فرعا الحكم المملوكي؛ حكم البحرية أولًا ثم البرجية قبل الفتح العثماني."},{"statement":"وقعت معركة الريدانية في بلاد الشام قبل وصول العثمانيين إلى مصر.","answer":false,"explanation":"الريدانية وقعت قرب القاهرة سنة 1517م؛ أما معركة الشام الحاسمة فهي مرج دابق سنة 1516م."},{"statement":"أُعدم طومان باي عند باب زويلة بعد انتهاء مقاومته.","answer":true,"explanation":"يرتبط باب زويلة بنهاية آخر محاولات طومان باي لحفظ الحكم المملوكي المستقل."},{"statement":"انتهت مرج دابق بانتصار المماليك وتراجع العثمانيين إلى الأناضول.","answer":false,"explanation":"انتصر العثمانيون في مرج دابق، ففُتح لهم طريق الشام ثم تقدموا إلى مصر."}],"essay":[{"question":"تتبع مراحل تقدم العثمانيين من مرج دابق حتى السيطرة على مصر.","answer":"انتصر العثمانيون في مرج دابق سنة 1516م وسيطروا على الشام، ثم تقدموا إلى مصر ووقعت الريدانية سنة 1517م. واصل طومان باي المقاومة بعد المعركة قبل أن ينتهي الحكم المملوكي المستقل."},{"question":"اشرح دور طومان باي في مقاومة السيطرة العثمانية على مصر.","answer":"قاد طومان باي الدفاع عن مصر في معركة الريدانية سنة 1517م، ثم حاول مواصلة المقاومة بعد تراجع المماليك. انتهت محاولته بأسره وإعدامه عند باب زويلة، وهو حدث يرمز إلى نهاية الحكم المملوكي المستقل."},{"question":"ما العوامل التي مهدت لتوسع الدولة العثمانية في مصر والشام؟","answer":"ساعد توسع العثمانيين العسكري والسياسي، وضعف الدولة المملوكية وصراعاتها الداخلية، وأهمية طرق التجارة والبلاد العربية على تصاعد المواجهة. انتهى الصدام في الشام بمرج دابق ثم انتقل إلى مصر."},{"question":"قارن بين مرج دابق والريدانية من حيث المكان والتاريخ والنتيجة.","answer":"وقعت مرج دابق في الشام سنة 1516م وانتهت بانتصار عثماني ومهدت للسيطرة على الشام. وقعت الريدانية قرب القاهرة سنة 1517م، وأدت إلى سقوط دفاع المماليك عن مصر، مع استمرار مقاومة طومان باي بعد المعركة."}]},"modern-history/lecture-02":{"source":"د. حسين السيد، تاريخ مصر الحديث، المحاضرة 2، PDF 5 صفحات","trueFalse":[{"statement":"نظم قانون نامة مصر جوانب من إدارة الولاية والحامية العثمانية.","answer":true,"explanation":"حدد الإطار الإداري والعسكري بعد الفتح، ومنه توزيع المسؤوليات وتنظيم الأوجاقات في مصر."},{"statement":"اقتصر تاريخ مصر العثمانية على الجيش من دون نشاط زراعي أو تعليمي.","answer":false,"explanation":"استمرت الزراعة والصناعة والتجارة، كما بقي الأزهر وحركة التأليف جزءًا من الحياة الفكرية."},{"statement":"صدر قانون نامة مصر في عهد السلطان سليمان القانوني سنة 1525م.","answer":true,"explanation":"نظم القانون مؤسسات الحكم العثماني في مصر بعد المرحلة الانتقالية التي أعقبت الفتح."},{"statement":"كانت الأوجاقات السبعة محاكم مدنية لا تشكيلات عسكرية.","answer":false,"explanation":"الأوجاقات وحدات الحامية العسكرية العثمانية، ولها دور في توازن القوة داخل الولاية."},{"statement":"واصل الأزهر دوره في التعليم خلال العصر العثماني.","answer":true,"explanation":"ظل مركزًا لتدريس العلوم الشرعية واللغة رغم مظاهر الجمود التي تناولتها كتابات الفترة."},{"statement":"توقفت الزراعة في مصر العثمانية ولم تعد مصدرًا اقتصاديًا مهمًا.","answer":false,"explanation":"ظلت الزراعة ركيزة للاقتصاد، إلى جانب الصناعة والتجارة والجباية المرتبطة بالأرض."}],"essay":[{"question":"كيف نظمت الإدارة العثمانية الحكم والحامية العسكرية في مصر؟","answer":"اعتمدت السلطة في البداية سياسة انتقالية، ثم نظم قانون نامة مصر الحكم والحامية العسكرية في أوجاقات. نشأ توازن معقد بين الوالي والقوى العسكرية والإدارية المحلية."},{"question":"لخص جوانب الاقتصاد والمجتمع والحياة الفكرية في مصر العثمانية.","answer":"تتناول الزراعة والصناعة والتجارة، ثم الطبقات الاجتماعية، وأخيرًا التعليم وحركة التأليف وأعلام التاريخ واللغة، مع مناقشة مظاهر الجمود الفكري في الفترة."},{"question":"اشرح أثر تنظيم الأوجاقات في توازن السلطة بمصر العثمانية.","answer":"شكلت الأوجاقات الحامية العسكرية المنظمة، فكان لها نفوذ إلى جانب الوالي والمؤسسات الإدارية. هذا التوازن يفسر جزءًا من تعقيد الحكم المحلي وتعدد مراكز القوة."},{"question":"اذكر ملامح الاقتصاد والتعليم في مصر خلال الحكم العثماني.","answer":"استند الاقتصاد إلى الزراعة والصناعة والتجارة مع نظام للجباية والأسواق. استمر الأزهر في التعليم، وظهرت مؤلفات في التاريخ واللغة، رغم ما رُصد من جمود فكري في بعض المجالات."}]},"modern-history/lecture-03":{"source":"د. حسين السيد، تاريخ مصر الحديث، المحاضرة 3، PDF 5 صفحات","trueFalse":[{"statement":"طرد علي بك الكبير الوالي العثماني سنة 1768م وعزز سلطته في مصر.","answer":true,"explanation":"بعد صعوده إلى منصب شيخ البلد، انفرد بالحكم ونصب نفسه قائم مقام في أكتوبر 1768م."},{"statement":"كانت معركة الصالحية بداية حركة علي بك الكبير.","answer":false,"explanation":"جاءت الصالحية سنة 1773م بعد سنوات من توسع علي بك وانقلاب محمد بك أبي الدهب عليه، وكانت من أحداث نهاية الحركة."},{"statement":"تولى علي بك الكبير منصب شيخ البلد قبل محاولة الاستقلال.","answer":true,"explanation":"أعطاه المنصب نفوذًا داخل نظام الحكم المملوكي في مصر العثمانية، ثم وسع سلطته."},{"statement":"ارتبط الشيخ همام وقبائل الهوارة بنفوذ قوي في صعيد مصر.","answer":true,"explanation":"كان إخضاع الصعيد جزءًا مهمًا من سعي علي بك إلى توحيد السلطة في البلاد."},{"statement":"ظل محمد بك أبو الدهب حليفًا لعلي بك حتى انتصاره الأخير في الصالحية.","answer":false,"explanation":"انقلب أبو الدهب على علي بك، وكان ذلك عاملًا حاسمًا في انهيار مشروعه."},{"statement":"سعى علي بك الكبير إلى تحالف عسكري مع فرنسا بدل روسيا القيصرية.","answer":false,"explanation":"بحث عن دعم روسيا في سياق صراعها مع العثمانيين، إلى جانب تحركاته مع ظاهر العمر في الشام."}],"essay":[{"question":"اشرح مراحل صعود علي بك الكبير ومحاولته الاستقلال عن الدولة العثمانية.","answer":"صعد علي بك إلى منصب شيخ البلد، ثم انفرد بالسلطة وطرد الوالي العثماني سنة 1768م. وسع نفوذه في الحجاز والشام، وسعى إلى التحالف مع الأسطول الروسي ضد العثمانيين."},{"question":"ما أسباب نهاية حركة علي بك الكبير؟","answer":"انقلب محمد بك أبو الدهب عليه، فانسحبت قوات حاسمة من مشروعه. حاول علي بك استرداد الحكم، لكنه هُزم وجُرح وأُسر في الصالحية سنة 1773م، ثم توفي متأثرًا بجراحه."},{"question":"لماذا كان إخضاع نفوذ الشيخ همام والهوارة مهمًا لعلي بك الكبير؟","answer":"كان للشيخ همام وقبائل الهوارة نفوذ واسع في صعيد مصر؛ ولذلك لم تكن سيطرة علي بك على القاهرة وحدها تكفي لتثبيت حكمه. ساعد إخضاع هذا النفوذ على توسيع سلطته جنوبًا."},{"question":"كيف حاول علي بك دعم مشروعه خارج مصر، ولماذا فشل في نهايته؟","answer":"توسع نحو الحجاز والشام، وتحالف مع ظاهر العمر، وسعى إلى دعم الأسطول الروسي ضد العثمانيين. لكن انقلاب محمد بك أبي الدهب عليه أضعف قواته، وانتهت عودته بالهزيمة في الصالحية سنة 1773م."}]},"modern-history/lecture-04":{"source":"د. حسين السيد، تاريخ مصر الحديث، المحاضرة 4، PDF 9 صفحات","trueFalse":[{"statement":"وقعت معركة أبي قير البحرية بعد وصول الحملة الفرنسية إلى مصر سنة 1798م.","answer":true,"explanation":"أنزل الفرنسيون قواتهم في الإسكندرية في يوليو، ثم وقعت أبي قير البحرية في أغسطس بعد تقدمهم بريًا."},{"statement":"خرج الأسطول الفرنسي من أبي قير البحرية أقوى مما كان قبلها.","answer":false,"explanation":"حطم الأسطول الإنجليزي بقيادة نيلسون القوة البحرية الفرنسية، فأضعف اتصال الحملة بفرنسا وإمدادها."},{"statement":"قاد محمد كريم مقاومة الإنزال الفرنسي في الإسكندرية.","answer":true,"explanation":"ارتبط اسمه بالدفاع عن المدينة عند وصول الحملة في يوليو 1798م."},{"statement":"قاد نيلسون الأسطول الإنجليزي في معركة أبي قير البحرية.","answer":true,"explanation":"أدت هزيمته للأسطول الفرنسي إلى عزل الحملة بحريًا وإضعاف قدرتها الاستراتيجية."},{"statement":"سبقت معركة أبي قير البحرية معركة إمبابة في تسلسل أحداث 1798م.","answer":false,"explanation":"وقعت إمبابة في 21 يوليو، ثم جرت أبي قير البحرية في أول أغسطس من العام نفسه."},{"statement":"كان هدف الحملة الفرنسية الوحيد إجراء بحوث أثرية من دون مصالح سياسية أو تجارية.","answer":false,"explanation":"ارتبط الغزو بضرب المصالح البريطانية في الشرق وتعزيز النفوذ الفرنسي، إلى جانب البعثة العلمية."}],"essay":[{"question":"تتبع العمليات العسكرية الأولى للحملة الفرنسية من الإنزال إلى معركة أبي قير البحرية.","answer":"بدأ الإنزال بالإسكندرية في يوليو 1798م، ثم تقدمت القوات الفرنسية نحو القاهرة ووقعت معركتا شبراخيت وإمبابة. وفي أغسطس وقعت معركة أبي قير البحرية التي دمر فيها الأسطول الفرنسي، بما غيّر وضع الحملة الاستراتيجي."},{"question":"اشرح أثر الهزيمة البحرية في أبي قير على موقف الحملة الفرنسية في مصر.","answer":"دمر الأسطول الإنجليزي بقيادة نيلسون القوة البحرية الفرنسية في أبي قير، فأضعف اتصال الحملة بفرنسا وقدرتها على تلقي الإمدادات، رغم نجاحها البري السابق قرب القاهرة."},{"question":"بيّن الأهداف السياسية والاقتصادية والعلمية للحملة الفرنسية على مصر.","answer":"هدفت فرنسا إلى ضرب طرق المصالح البريطانية في الشرق وتعزيز نفوذها في البحر المتوسط والتجارة، كما صاحب الحملة مشروع علمي لدراسة مصر وآثارها. لا يفسر هدف واحد وحده قرار الغزو."},{"question":"قارن بين مقاومة الإسكندرية والمماليك والصعيد في المرحلة الأولى من الحملة.","answer":"قاوم محمد كريم الإنزال في الإسكندرية، ثم واجه المماليك التقدم الفرنسي في شبراخيت وإمبابة. واستمرت في الصعيد أشكال من المقاومة وحرب الاستنزاف بعد سقوط القاهرة، مما يبين اتساع المواجهة جغرافيًا."}]},"modern-history/lecture-05":{"source":"د. حسين السيد، تاريخ مصر الحديث، المحاضرة 5، PDF 10 صفحات","trueFalse":[{"statement":"شهدت القاهرة ثورتها الثانية ومقاومة بولاق سنة 1800م.","answer":true,"explanation":"اندلعت الثورة في مارس وأبريل 1800م، وكانت بولاق من مراكز المقاومة الشعبية قبل قمعها."},{"statement":"استمر الحكم الفرنسي لمصر بعد انتصار الحملة سنة 1801م.","answer":false,"explanation":"هُزمت القوات الفرنسية في معركة كانوب، ثم انتهت الحملة باستسلام مينو ورحيلها سنة 1801م."},{"statement":"اندلعت ثورة القاهرة الأولى في أكتوبر 1798م.","answer":true,"explanation":"قاد الأزهر جانبًا مهمًا من المقاومة الشعبية في وقت كانت فيه الحملة تواجه صعوبات في إخضاع البلاد."},{"statement":"اغتيل الجنرال كليبر على يد سليمان الحلبي سنة 1800م.","answer":true,"explanation":"أدى اغتياله إلى انتقال قيادة الحملة إلى مينو في مرحلة تزايد الضغوط عليها."},{"statement":"كانت بولاق مركز ثورة القاهرة الأولى سنة 1798م وحدها.","answer":false,"explanation":"برزت بولاق خصوصًا في ثورة القاهرة الثانية سنة 1800م؛ أما الثورة الأولى فارتبطت بقوة بالأزهر وأحياء القاهرة."},{"statement":"استسلم مينو قبل معركة كانوب التي وقعت سنة 1801م.","answer":false,"explanation":"وقعت كانوب في مارس 1801م، ثم جاءت مراحل التراجع والاستسلام الفرنسي لاحقًا."}],"essay":[{"question":"اشرح صور المقاومة المصرية في أواخر فترة الحملة الفرنسية.","answer":"شهدت القاهرة ثورتها الثانية سنة 1800م، وبرز صمود بولاق وأحياء أخرى قبل قمعها. تواصلت المقاومة في وقت تعرضت فيه قيادة الحملة لتغيرات، ومنها اغتيال كليبر."},{"question":"تتبع أهم الأحداث التي أدت إلى رحيل الحملة الفرنسية سنة 1801م.","answer":"قاد مينو الحملة بعد كليبر، ثم تعرض الفرنسيون للهزيمة في كانوب في مارس 1801م. تقدمت القوات المناوئة نحو القاهرة والإسكندرية حتى انتهى الأمر باستسلام مينو ورحيل الحملة في أغسطس 1801م."},{"question":"قارن بين ثورتي القاهرة الأولى والثانية من حيث التوقيت ومراكز المقاومة.","answer":"اندلعت الأولى في أكتوبر 1798م وارتبطت بالأزهر وأحياء القاهرة، ثم قُمعت بعنف. وقعت الثانية في مارس وأبريل 1800م وبرز فيها صمود بولاق، وتعرضت هي الأخرى لقمع شديد."},{"question":"ما مصير حجر رشيد والآثار بعد استسلام القوات الفرنسية سنة 1801م؟","answer":"عند انتهاء الحملة واستسلام القوات الفرنسية نُقلت إلى البريطانيين بعض الآثار التي جمعها الفرنسيون، ومنها حجر رشيد. تكشف الواقعة جانبًا من نتائج الهزيمة يتجاوز الانسحاب العسكري."}]}};
